diff --git a/src/hb-gpu-paint.cc b/src/hb-gpu-paint.cc
index eeeec1e55..887459ade 100644
--- a/src/hb-gpu-paint.cc
+++ b/src/hb-gpu-paint.cc
@@ -716,7 +716,7 @@ hb_gpu_paint_emit_linear (hb_gpu_paint_t  *c,
    * untransformed space, so affine distortions of the axis are
    * handled exactly rather than approximated. */
   hb_vector_t<int16_t> grad_data;
-  if (unlikely (!grad_data.resize (8)))
+  if (unlikely (!grad_data.resize (12)))
   { c->unsupported = true; return; }

   float lx0, ly0, lx1, ly1;
@@ -740,6 +740,10 @@ hb_gpu_paint_emit_linear (hb_gpu_paint_t  *c,
   grad_data[5] = Linv[1];
   grad_data[6] = Linv[2];
   grad_data[7] = Linv[3];
+  grad_data[8] = 0;
+  grad_data[9] = 0;
+  grad_data[10] = 0;
+  grad_data[11] = 0;

   if (unlikely (!append_color_stops (grad_data, stops, got)))
   { c->unsupported = true; return; }
@@ -936,7 +940,7 @@ hb_gpu_paint_emit_sweep (hb_gpu_paint_t  *c,
    * handled exactly.
    */
   hb_vector_t<int16_t> grad_data;
-  if (unlikely (!grad_data.resize (8)))
+  if (unlikely (!grad_data.resize (12)))
   { c->unsupported = true; hb_free (heap_stops); return; }

   float mn, mx;
@@ -963,6 +967,10 @@ hb_gpu_paint_emit_sweep (hb_gpu_paint_t  *c,
   grad_data[5] = Linv[1];
   grad_data[6] = Linv[2];
   grad_data[7] = Linv[3];
+  grad_data[8] = 0;
+  grad_data[9] = 0;
+  grad_data[10] = 0;
+  grad_data[11] = 0;

   if (unlikely (!append_color_stops (grad_data, stops, got)))
   { c->unsupported = true; hb_free (heap_stops); return; }

