@@ -1467,12 +1467,7 @@ hb_gpu_paint_encode (hb_gpu_paint_t     *paint,
   const unsigned texel_bytes   = 8;

   unsigned ops_texels = paint->ops.length / 4;
-  unsigned sub_bytes = 0;
-  for (hb_blob_t *b : paint->sub_blobs)
